async *queryStream(
  req: QueryRequest,
  tenantId: string = 'default',
): AsyncGenerator<RagStreamEvent, void, unknown> {
  const res = await fetch(`${this.baseUrl}/v1/query/stream`, {
    method: 'POST',
    headers: this.getHeaders(tenantId),
    body: JSON.stringify({
      query: req.query,
      tenant_id: tenantId || 'default',
      top_k: req.top_k ?? 3,
      max_cycles: req.max_cycles ?? 3,
      enforce_guardrails: req.enforce_guardrails ?? true,
    }),
  });
  if (!res.ok || !res.body) {
    const errorData = await res.json().catch(() => ({ detail: res.statusText })) as ApiErrorPayload;
    const detail = normalizeDetail(errorData.error?.message ?? errorData.detail, `Query failed: ${res.statusText}`);
    throw new ApiError(detail, res.status, detail);
  }
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let boundary = buffer.indexOf('\n\n');
      while (boundary !== -1) {
        const chunk = buffer.slice(0, boundary);
        buffer = buffer.slice(boundary + 2);
        let eventName = 'message';
        const dataLines: string[] = [];
        for (const line of chunk.split('\n')) {
          if (line.startsWith('event:')) eventName = line.slice(6).trim();
          else if (line.startsWith('data:')) dataLines.push(line.slice(5).trim());
        }
        const data = dataLines.join('\n');
        if (data) {
          try {
            const parsed = JSON.parse(data) as Record<string, unknown>;
            yield { type: eventName, ...parsed } as RagStreamEvent;
          } catch {
            // Ignore malformed frames; keep streaming.
          }
        }
        boundary = buffer.indexOf('\n\n');
      }
    }
  } finally {
    reader.releaseLock();
  }
}

